question:
What is the time complexity of this function?

int sum(int arr[], int n) {
  int total = 0;
  for (int i = 0; i < n; i++) {
    total += arr[i];
  }
  return total;
}

What is the time complexity of this function?

void pairs(int arr[], int n) {
  for (int i = 0; i < n; i++)
    for (int j = 0; j < n; j++)
      printf("%d%d ", arr[i], arr[j]);
}

What is the time complexity of this function?

int steps(int n) {
  int count = 0;
  while (n > 1) {
    n = n / 2;
    count++;
  }
  return count;
}
